begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
create temporary table tap_results(line text);
grant all on tap_results to authenticated;
create function pg_temp.i(n integer) returns uuid language sql immutable as $$select ('60000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid$$;
insert into auth.users(id,email) values(pg_temp.i(1),'branch-owner@example.invalid'),(pg_temp.i(2),'branch-cashier@example.invalid'),(pg_temp.i(3),'branch-other@example.invalid');
insert into auth.sessions(id,user_id) select id,id from auth.users where id in(pg_temp.i(1),pg_temp.i(2),pg_temp.i(3));
select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.i(1),'session_id',pg_temp.i(1))::text,true);
set local role authenticated;
select public.agri_command('bootstrap','{"name":"TEST branch expansion"}');
reset role;
create function pg_temp.org() returns uuid language sql stable as $$select organization_id from public.staff_memberships where user_id=pg_temp.i(1)$$;
create function pg_temp.request(n integer, name text default 'Test added branch') returns jsonb language sql stable as $$select jsonb_build_object('organizationId',pg_temp.org(),'newBranchId',pg_temp.i(n),'name',name)$$;
insert into public.staff_memberships(organization_id,user_id,branch_id,role,name) values(pg_temp.org(),pg_temp.i(2),(select id from public.branches where organization_id=pg_temp.org() and code='B01'),'cashier','Test cashier');
set local role authenticated;
insert into tap_results select lives_ok($$select public.agri_command('create_branch',pg_temp.request(4))$$,'Owner adds a fourth branch');
insert into tap_results select lives_ok($$select public.agri_command('create_branch',pg_temp.request(5))$$,'Owner adds a fifth branch');
insert into tap_results select is((select count(*)::integer from public.branches),5,'Business is no longer limited to three branches');
insert into tap_results select is((select code from public.branches where id=pg_temp.i(5)),'B05','New branch receives the next stable code');
insert into tap_results select lives_ok($$select public.agri_command('create_branch',pg_temp.request(5))$$,'Lost branch response can be retried');
insert into tap_results select is((select count(*)::integer from public.audit_events where action='create_branch'),2,'Retry creates neither duplicate branch nor audit event');
insert into tap_results select throws_ok($$select public.agri_command('create_branch',pg_temp.request(5,'Changed content'))$$,'P0001','Branch request ID conflict','Changed retry is a visible conflict');
insert into tap_results select throws_ok($$select public.agri_command('create_branch',pg_temp.request(6,'   '))$$,'P0001','Enter a branch name with 1 to 120 characters','Blank names are rejected');
insert into tap_results select throws_ok($$select public.agri_command('create_branch',pg_temp.request(6,repeat('x',121)))$$,'P0001','Enter a branch name with 1 to 120 characters','Overlong names are rejected');
insert into tap_results select lives_ok($$select public.agri_command('rename_branch',jsonb_build_object('organizationId',pg_temp.org(),'branchId',pg_temp.i(5),'name','  Sample Branch C  '))$$,'Owner renames an added branch');
insert into tap_results select is((select name from public.branches where id=pg_temp.i(5)),'Sample Branch C','Names are trimmed');
insert into tap_results select lives_ok($$select public.agri_command('create_branch',pg_temp.request(5))$$,'Original create retry stays valid after a later rename');
insert into tap_results select is((select name from public.branches where id=pg_temp.i(5)),'Sample Branch C','Retry does not overwrite a later rename');
reset role;
insert into public.branches(organization_id,name,code) values(pg_temp.org(),'Test 99','B99');
set local role authenticated;
insert into tap_results select lives_ok($$select public.agri_command('create_branch',pg_temp.request(100))$$,'Branch numbers can exceed 99');
insert into tap_results select is((select code from public.branches where id=pg_temp.i(100)),'B100','Three-digit codes are not truncated');
reset role;
select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.i(2),'session_id',pg_temp.i(2))::text,true);
-- Keep the target org literal in a temp setting because cashier RLS hides owner membership.
select set_config('test.branch_org',pg_temp.org()::text,true);
set local role authenticated;
insert into tap_results select throws_ok($$select public.agri_command('create_branch',jsonb_build_object('organizationId',current_setting('test.branch_org'),'newBranchId',pg_temp.i(7),'name','Forbidden'))$$,'42501','Only the owner can manage branches','Cashier cannot add a branch');
reset role;
select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.i(3),'session_id',pg_temp.i(3))::text,true);
set local role authenticated;
select public.agri_command('bootstrap','{"name":"TEST other branch business"}');
insert into tap_results select throws_ok($$select public.agri_command('create_branch',jsonb_build_object('organizationId',current_setting('test.branch_org'),'newBranchId',pg_temp.i(7),'name','Forbidden'))$$,'42501','Only the owner can manage branches','Another organization owner cannot add a branch here');
insert into tap_results select throws_ok($$select public.agri_command('rename_branch',jsonb_build_object('organizationId',current_setting('test.branch_org'),'branchId',pg_temp.i(5),'name','Forbidden'))$$,'42501','Only the owner can manage branches','Cross-organization rename is denied');
reset role;
select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.i(1),'session_id',pg_temp.i(1))::text,true);
update public.staff_memberships set active=false where user_id=pg_temp.i(1);
set local role authenticated;
insert into tap_results select throws_ok($$select public.agri_command('create_branch',jsonb_build_object('organizationId',current_setting('test.branch_org'),'newBranchId',pg_temp.i(7),'name','Forbidden'))$$,'42501','Only the owner can manage branches','Revoked owner cannot add branches');
reset role;
delete from auth.sessions where id=pg_temp.i(1);
set local role authenticated;
insert into tap_results select throws_ok($$select public.agri_command('create_branch',jsonb_build_object('organizationId',current_setting('test.branch_org'),'newBranchId',pg_temp.i(7),'name','Forbidden'))$$,'42501','Sign in again before making online changes','Revoked session cannot manage branches');
reset role;
insert into tap_results select ok(not has_function_privilege('anon','public.agri_command(text,jsonb)','execute'),'Anonymous callers cannot execute branch commands');
insert into tap_results select * from finish();
select line from tap_results;
rollback;
